export const PALETTES: { readonly [slug: string]: BeadsPaletteEntry } = (() => {
  const out: { [slug: string]: BeadsPaletteEntry } = {};
  for (const slug in RAW) {
    const r = RAW[slug]!;
    const d = decodeEntry(r[0]);
    out[slug] = { codes: d.codes, palette: d.palette, source: r[1], note: r[2] };
  }
  return Object.freeze(out);
})();
